// `added` is when the row was posted: a date, or a full UTC time ('2026-10-27T23:05:00Z') for newer rows.
const rows = (kind, list) =>
  list.map(({ added, opensOn, ...o }) => ({
    ...build(kind, { verified: added?.slice(0, 10), posted: added, ...o }, SOURCE),
    // Not open yet: hidden until `opensOn`, then shown as newly posted.
    ...(opensOn ? { opensOn } : {}),
  }))

// Scholarship rows carry `funding`; every other type carries `category`. A scholarship
// appended to the wrong array by mistake is still listed as a scholarship.
const isScholarship = (row) => row.funding && !row.category
const others = [fellowshipRows, grantRows, internshipRows, competitionRows]
const proper = (list) => list.filter((row) => !isScholarship(row))

export const autoScholarships = rows('scholarships', [...scholarshipRows, ...others.flatMap((list) => list.filter(isScholarship))])
export const autoFellowships = rows('fellowships', proper(fellowshipRows))
export const autoGrants = rows('grants', proper(grantRows))
export const autoInternships = rows('internships', proper(internshipRows))
export const autoCompetitions = rows('competitions', proper(competitionRows))
